import React, { useState, useEffect } from 'react';
import './Dashboard.css';

function Dashboard() {
  const [stats, setStats] = useState({
    complianceScore: 0,
    breachCount: 0,
    tablesFound: 0,
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchStats();
  }, []);

  const fetchStats = async () => {
    try {
      // Get compliance score
      const complianceRes = await fetch('/api/compliance/score');
      const complianceData = await complianceRes.json();

      // Get breaches count
      const breachRes = await fetch('/api/breaches');
      const breachData = await breachRes.json();

      // Get tables count
      const discoveryRes = await fetch('/api/discovery/scan', {
        method: 'POST',
      });
      const discoveryData = await discoveryRes.json();

      setStats({
        complianceScore: complianceData.score || 0,
        breachCount: breachData.length || 0,
        tablesFound: discoveryData.totalTables || 0,
      });
    } catch (error) {
      console.error('Error fetching stats:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div className="container"><p>Loading dashboard...</p></div>;
  }

  return (
    <div className="container">
      <div className="dashboard-header">
        <h1>📊 DPDP Compliance Dashboard</h1>
        <p className="subtitle">Digital Personal Data Protection Act Compliance Platform</p>
      </div>

      <div className="stats-grid">
        <div className="stat-card compliance">
          <div className="stat-icon">✓</div>
          <div className="stat-content">
            <div className="stat-number">{stats.complianceScore}%</div>
            <div className="stat-label">Compliance Score</div>
            <div className="stat-progress">
              <div className="stat-bar" style={{ width: `${stats.complianceScore}%` }}></div>
            </div>
          </div>
        </div>

        <div className="stat-card discovery">
          <div className="stat-icon">📊</div>
          <div className="stat-content">
            <div className="stat-number">{stats.tablesFound}</div>
            <div className="stat-label">Tables Discovered</div>
            <div className="stat-desc">Database records found</div>
          </div>
        </div>

        <div className="stat-card breach">
          <div className="stat-icon">🚨</div>
          <div className="stat-content">
            <div className="stat-number">{stats.breachCount}</div>
            <div className="stat-label">Breaches Reported</div>
            <div className="stat-desc">Incidents logged</div>
          </div>
        </div>
      </div>

      <div className="info-section">
        <h2>🎯 Key Features</h2>
        <div className="features-grid">
          <div className="feature-card">
            <h3>📊 Data Discovery</h3>
            <p>Automatically scan your databases and identify all personal data locations. Detect PII patterns across tables.</p>
          </div>
          <div className="feature-card">
            <h3>✓ Compliance Checklist</h3>
            <p>Track 20 DPDP compliance items organized by category. Monitor progress toward full compliance by May 2027.</p>
          </div>
          <div className="feature-card">
            <h3>🚨 Breach Alert</h3>
            <p>Report data breaches and auto-generate official DPB notification letters. Stay compliant with notification requirements.</p>
          </div>
        </div>
      </div>

      <div className="info-section">
        <h2>📅 DPDP Timeline</h2>
        <div className="timeline">
          <div className="timeline-item completed">
            <div className="timeline-dot"></div>
            <div className="timeline-content">
              <h4>August 2023</h4>
              <p>DPDP Act Enacted</p>
            </div>
          </div>
          <div className="timeline-item completed">
            <div className="timeline-dot"></div>
            <div className="timeline-content">
              <h4>November 2025</h4>
              <p>DPDP Rules 2025 Notified</p>
            </div>
          </div>
          <div className="timeline-item active">
            <div className="timeline-dot"></div>
            <div className="timeline-content">
              <h4>May 2027</h4>
              <p>Full Compliance Deadline ⚠️</p>
            </div>
          </div>
        </div>
      </div>

      <div className="cta-section">
        <h2>🚀 Get Started</h2>
        <p>Navigate using the menu on the left to access each module:</p>
        <ul className="cta-list">
          <li><strong>📊 Data Discovery</strong> - Scan your databases first</li>
          <li><strong>✓ Compliance</strong> - Track your compliance progress</li>
          <li><strong>🚨 Breach Alert</strong> - Report and manage incidents</li>
        </ul>
      </div>
    </div>
  );
}

export default Dashboard;
